    fn board_with(projects: Vec<Project>, model_swaps: bool) -> Switchboard {
        Switchboard::new(
            Registry::new(projects),
            "pi".into(),
            None,
            "".into(),
            None,
            None,
            None,
            "medium".into(),
            ".cache".into(),
