		startCancelled = true;
		setRecordingUI(false);
		return;
	}
	if (mediaRecorder && mediaRecorder.state !== "inactive") {
		mediaRecorder.stop();
	}
	setRecordingUI(false);
}

function isRecording(): boolean {
	return mediaRecorder?.state === "recording";
}

